function validate(input) {
  const [{ Accounts = [], Logins = [] }] = input;
  const ids = new Set();
  for (const [id, name] of Accounts) {
    if (id === null || name === null) return 'Every account needs an id and a name.';
    if (ids.has(id)) return `Account id ${id} appears twice.`;
    ids.add(id);
  }
  for (const [id, date] of Logins) {
    if (!ids.has(id)) return `Login id ${id} is not an account.`;
    if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date) || Number.isNaN(Date.parse(`${date}T00:00:00Z`))) return 'login_date must be a date like 2020-05-30.';
  }
  return null;
}

