function generate(rand, size) {
  const small = size === 'small';
  const day = offset => new Date(Date.UTC(small ? 2020 : 2019, small ? 4 : 10, small ? 25 : 1) + offset * 86400000).toISOString().slice(0, 10);
  const names = ['Winston', 'Jonathan', 'Mia', 'Omar', 'Rosa', 'Lee', 'Priya', 'Sam'];
  const accountCount = small ? Math.floor(rand() * 4) : 200;
  const ids = [];
  for (let id = 1; id <= (small ? 6 : 400); id++) ids.push(id);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Accounts = ids.slice(0, accountCount).map(id => [id, names[Math.floor(rand() * names.length)]]);
  const Logins = [];
  if (!Accounts.length) return [{ Accounts, Logins }];
  const someone = () => Accounts[Math.floor(rand() * Accounts.length)][0];
  if (small) {
    // One near-miss or winning streak of 3 to 6 days, then a few duplicates, neighbours or strays.
    if (rand() < 0.7) {
      const who = someone(), start = Math.floor(rand() * 10), length = 3 + Math.floor(rand() * 4);
      for (let k = 0; k < length; k++) if (rand() < 0.92) Logins.push([who, day(start + k)]);
    }
    while (Logins.length < 8 && rand() < 0.6) {
      const r = rand();
      if (r < 0.3 && Logins.length) Logins.push(Logins[Math.floor(rand() * Logins.length)].slice());
      else if (r < 0.6 && Logins.length) { const [who, date] = Logins[Logins.length - 1]; Logins.push([who, day(Math.round((Date.parse(date) - Date.UTC(2020, 4, 25)) / 86400000) + 1 + Math.floor(rand() * 2))]); }
      else Logins.push([someone(), day(Math.floor(rand() * 14))]);
    }
    for (let i = Logins.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Logins[i], Logins[j]] = [Logins[j], Logins[i]]; }
  } else {
    // Runs of 1 to 7 days scattered over about 400 days, crossing a year end, with some repeated logins.
    while (Logins.length < 2000) {
      const who = someone(), start = Math.floor(rand() * 400), length = 1 + Math.floor(rand() * 7);
      for (let k = 0; k < length && Logins.length < 2000; k++) {
        Logins.push([who, day(start + k)]);
        if (rand() < 0.1 && Logins.length < 2000) Logins.push([who, day(start + k)]);
      }
    }
  }
  return [{ Accounts, Logins }];
}
